    // Converts the task ids (1 for letter, 2 for package) to the corresponding number of required actions
    public int idToHits(int id){
        switch (id)
        {
            case 1: return hitsPerLetter;
            case 2: return hitsPerPackage;
            default: return 0;
        }
    }

